// ---------- helpers ----------
function parseCSV(text) {
  const rows = []; let row = []; let f = ''; let q = false;
  const s = text.replace(/^﻿/, '');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) {
      if (c === '"') { if (s[i + 1] === '"') { f += '"'; i++; } else q = false; }
      else f += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(f); f = ''; }
    else if (c === '\n') { row.push(f); rows.push(row); row = []; f = ''; }
    else if (c !== '\r') f += c;
  }
  if (f !== '' || row.length) { row.push(f); rows.push(row); }
  const clean = rows.filter(r => !(r.length === 1 && r[0].trim() === ''));
  const header = clean.shift().map(h => h.trim());
  return { header, records: clean.map((r, idx) => {
    if (r.length !== header.length) throw new Error(`MIRA_INVALID_CSV: wrong column count on data row ${idx + 1}`);
    return Object.fromEntries(header.map((h, k) => [h, r[k].trim()]));
  }) };
}
function requireHeaders(name, header, expected) {
  const missing = expected.filter(h => !header.includes(h));
  if (missing.length) throw new Error(`MIRA_INVALID_HEADERS in ${name}: missing ${missing.join(', ')}`);
}
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const toMs = iso => Date.parse(iso + 'T00:00:00Z');
const addDays = (iso, n) => new Date(toMs(iso) + n * 86400000).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((toMs(b) - toMs(a)) / 86400000);
const splitList = s => s.split(';').map(x => x.trim()).filter(Boolean);

// ---------- settings (from the "Mira Settings" node) ----------
const today = new Date().toISOString().slice(0, 10);
const reporting_date = $json.use_today_as_reporting_date === true ? today : String($json.reporting_date || today);
const project_start_date = String($json.project_start_date || '');
const at_risk_window_days = Number($json.at_risk_window_days) || 7;
const default_horizon_days = Number($json.milestone_default_horizon_days) || 14;
if (!ISO.test(reporting_date) || isNaN(toMs(reporting_date))) throw new Error('MIRA_INVALID_SETTINGS: reporting_date must be YYYY-MM-DD');
if (project_start_date && (!ISO.test(project_start_date) || isNaN(toMs(project_start_date)))) throw new Error('MIRA_INVALID_SETTINGS: project_start_date must be YYYY-MM-DD');

// ---------- project description ----------
const paragraphs = PROJECT_DESCRIPTION.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean)
  .filter(p => !/^AI Adoption Project Description/i.test(p))
  .map((text, i) => ({ id: `P${i + 1}`, text }));
if (!paragraphs.length) throw new Error('MIRA_EMPTY_DESCRIPTION');
const fullDesc = paragraphs.map(p => p.text).join(' ');
const goalsMatch = fullDesc.match(/Key goals include ([^.]+)\./i);
const stated_goals = goalsMatch ? goalsMatch[1].split(/,\s*(?:and\s+)?|\s+and\s+/).map(s => s.trim()).filter(Boolean) : [];
const focusMatch = fullDesc.match(/core business functions, including ([^.]+)\./i);
const focus_areas = focusMatch ? focusMatch[1].split(/,\s*(?:and\s+)?|\s+and\s+/).map(s => s.trim()).filter(Boolean) : [];

// ---------- timeline ----------
const tl = parseCSV(TIMELINE_CSV);
requireHeaders('project_timeline.csv', tl.header, ['phase', 'phase_name', 'start_week', 'end_week', 'key_activities', 'milestones_deliverables']);
let prevEnd = 0;
const timeline = tl.records.map(r => {
  const phase = Number(r.phase), sw = Number(r.start_week), ew = Number(r.end_week);
  if (!Number.isInteger(phase) || !Number.isInteger(sw) || !Number.isInteger(ew) || sw !== prevEnd + 1 || ew < sw)
    throw new Error(`MIRA_INVALID_TIMELINE: phase ${r.phase} has a non-contiguous week range`);
  prevEnd = ew;
  const start_date = project_start_date ? addDays(project_start_date, (sw - 1) * 7) : null;
  const end_date = project_start_date ? addDays(project_start_date, ew * 7 - 1) : null;
  return { phase, phase_name: r.phase_name, start_week: sw, end_week: ew, start_date, end_date,
    activities: splitList(r.key_activities), milestones: splitList(r.milestones_deliverables) };
});

// ---------- risks ----------
const rk = parseCSV(RISKS_CSV);
requireHeaders('project_risks.csv', rk.header, ['risk_id', 'category', 'risk_challenge', 'impact', 'mitigation_strategy']);
const risks = rk.records.map(r => {
  if (!/^R\d{2}$/.test(r.risk_id)) throw new Error(`MIRA_INVALID_RISK_ID: ${r.risk_id}`);
  return r;
});

// ---------- task board ----------
const tb = parseCSV(TASK_BOARD_CSV);
const TASK_COLS = ['task_id', 'task_name', 'status', 'assignee', 'priority', 'sprint', 'due_date', 'labels', 'description'];
requireHeaders('sample_task_board.csv', tb.header, TASK_COLS);
const STATES = ['Done', 'In Progress', 'Blocked', 'To Do'];
const seen = new Set();
// Task → phase link: by work-type label first (board due dates run ahead of the timeline),
// falling back to the due date for labels with no obvious phase (e.g. Security, Compliance).
const PHASE_BY_LABEL = { 'Planning': 1, 'Analysis': 2, 'Use Cases': 3, 'Data Prep': 4, 'Model Dev': 4, 'Pilot': 5, 'Evaluation': 6, 'Deployment': 7, 'Monitoring': 8 };
const phaseForDate = d => {
  if (!project_start_date) return null;
  const p = timeline.find(ph => d >= ph.start_date && d <= ph.end_date);
  return p ? p.phase : null;
};
const tasks = tb.records.map(t => {
  if (!/^T\d{3}$/.test(t.task_id)) throw new Error(`MIRA_INVALID_TASK_ID: ${t.task_id}`);
  if (seen.has(t.task_id)) throw new Error(`MIRA_DUPLICATE_TASK: ${t.task_id}`);
  seen.add(t.task_id);
  if (!STATES.includes(t.status)) throw new Error(`MIRA_INVALID_STATUS: ${t.task_id} has "${t.status}"`);
  if (!/^Sprint [1-9]\d*$/.test(t.sprint)) throw new Error(`MIRA_INVALID_SPRINT: ${t.task_id}`);
  if (!ISO.test(t.due_date) || isNaN(toMs(t.due_date))) throw new Error(`MIRA_INVALID_DATE: ${t.task_id}`);
  const open = t.status !== 'Done';
  const days_to_due = daysBetween(reporting_date, t.due_date);
  return { ...t, sprint_no: Number(t.sprint.split(' ')[1]), days_to_due,
    overdue: open && days_to_due < 0,
    due_soon: open && days_to_due >= 0 && days_to_due <= at_risk_window_days,
    phase: PHASE_BY_LABEL[t.labels] ?? phaseForDate(t.due_date),
    phase_basis: PHASE_BY_LABEL[t.labels] ? 'label' : 'due date' };
});
const sprints = [...new Set(tasks.map(t => t.sprint_no))].sort((a, b) => a - b);

// ---------- risk → task-board evidence map (documented assumption, edit freely) ----------
// A task is linked to a risk if one of its labels matches, or its NAME contains a keyword.
const risk_signal_map = {
  R01: { labels: ['Analysis', 'Data Prep'], keywords: ['data quality', 'data gap', 'data clean'] },
  R02: { labels: [], keywords: ['integrat', 'deploy', 'rollout'] },
  R03: { labels: [], keywords: ['hire', 'skill'], workload: true },
  R04: { labels: [], keywords: ['staff training', 'pilot', 'feedback', 'adoption'] },
  R05: { labels: ['Compliance'], keywords: ['legal', 'privacy', 'compliance'] },
  R06: { labels: [], keywords: ['vendor', 'budget', 'cost'] },
  R07: { labels: [], keywords: ['success criteria', 'stakeholder', 'kpi'] },
  R08: { labels: ['Monitoring'], keywords: ['monitor', 'drift', 'retrain', 'iterate'] },
  R09: { labels: ['Security'], keywords: ['security', 'penetration', 'vulnerab'] },
  R10: { labels: [], keywords: ['vendor', 'platform'] },
};

const current_phase = timeline.find(p => p.start_date && reporting_date >= p.start_date && reporting_date <= p.end_date) || null;

return {
  json: {
    ...$json,
    kb: {
      project: { id: 'abcde_ai_adoption', client: 'ABCDE Ltd.', name: 'AI Adoption Project', paragraphs, stated_goals, focus_areas },
      timeline, risks, tasks, sprints, risk_signal_map,
      reporting_date, project_start_date, at_risk_window_days, default_horizon_days,
      current_phase: current_phase ? current_phase.phase : null,
      date_basis: $json.use_today_as_reporting_date === true ? 'live (today)' : 'configured snapshot date',
      sources: ['project_description.txt', 'project_timeline.csv', 'project_risks.csv', 'sample_task_board.csv'],
    },
  },
};

// Mira v2 · Route Validator & Sufficiency Gate
// Never trusts the LLM blindly: allow-lists the intent, sanitises parameters, applies
// deterministic guardrails, and converts insufficient requests into CLARIFY.
const base = $('Project Knowledge Base').item.json;
const kb = base.kb;
const rawText = String($json.text ?? '').trim();

let r = null;
try { r = JSON.parse(rawText.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { r = null; }

const INTENTS = ['PLAN', 'RISK', 'STATUS', 'MILESTONES', 'COMMS', 'RESOURCES', 'AMBIGUOUS', 'UNSUPPORTED'];
const SPECIALISTS = ['PLAN', 'RISK', 'STATUS', 'MILESTONES', 'COMMS', 'RESOURCES'];
const notes = [];
const pick = (v, allowed, dflt = null) => (allowed.includes(v) ? v : dflt);
const toInt = v => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Math.trunc(Number(v)));

let intent = r ? pick(String(r.intent || '').toUpperCase(), INTENTS) : null;
if (!intent) { intent = 'AMBIGUOUS'; notes.push('router_output_invalid_or_unparseable'); }

const p = {
  project_ref: r ? pick(String(r.project_ref || '').toUpperCase(), ['ABCDE', 'OTHER', 'NONE'], 'NONE') : 'NONE',
  sufficient: r ? r.sufficient === true : false,
  missing_info: Array.isArray(r?.missing_info) ? r.missing_info.map(x => String(x).slice(0, 80)).slice(0, 8) : [],
  sprint: toInt(r?.sprint),
  horizon_days: toInt(r?.horizon_days),
  top_n: toInt(r?.top_n),
  focus: pick(r?.focus, ['full_report', 'blocked_and_at_risk', 'counts_only']),
  audience: pick(r?.audience, ['leadership', 'engineering', 'client', 'general']),
  risk_ids: Array.isArray(r?.risk_ids) ? r.risk_ids.map(String).map(s => s.toUpperCase()).filter(s => /^R\d{2}$/.test(s)) : [],
  reason: String(r?.reason ?? '').slice(0, 300),
  confidence: Number.isFinite(Number(r?.confidence)) ? Number(r.confidence) : 0,
};

// ---- deterministic guardrails (belt and braces around the LLM) ----
const req = base.request.toLowerCase();
if (/\b(ignore|disregard|override)\b.{0,40}\b(rules|instructions|prompt|policy)\b/.test(req) || /\bjailbreak\b/.test(req)) {
  intent = 'UNSUPPORTED'; notes.push('prompt_injection_pattern');
}
if (!base.request) { intent = 'AMBIGUOUS'; notes.push('empty_request'); }
if (p.sprint === null) { const m = req.match(/\bsprint\s*#?\s*(\d{1,2})\b/); if (m) p.sprint = Number(m[1]); }
if (p.horizon_days === null) {
  const words = { one: 1, two: 2, three: 3, four: 4, a: 1 };
  const m = req.match(/\bnext\s+(\d+|one|two|three|four|a)\s+(day|week|month)s?\b/);
  if (m) { const n = words[m[1]] ?? Number(m[1]); p.horizon_days = n * (m[2] === 'week' ? 7 : m[2] === 'month' ? 30 : 1); }
}
if (p.top_n === null) { const m = req.match(/\btop\s+(\d{1,2})\b/); if (m) p.top_n = Number(m[1]); }
if (p.horizon_days !== null) p.horizon_days = Math.min(Math.max(p.horizon_days, 1), 180);
if (p.top_n !== null) p.top_n = Math.min(Math.max(p.top_n, 1), kb.risks.length);

let route = intent;
let clarify_for = null;
const gate = (why, missing = []) => {
  route = 'CLARIFY'; clarify_for = intent; notes.push(why);
  for (const m of missing) if (!p.missing_info.includes(m)) p.missing_info.push(m);
};

if (intent === 'AMBIGUOUS') { route = 'CLARIFY'; clarify_for = 'GENERAL'; }
else if (SPECIALISTS.includes(intent)) {
  const words = base.request.split(/\s+/).filter(Boolean).length;
  // Unknown sprint / risk IDs are checked first: the router may also mark these "insufficient",
  // and the user deserves the specific reason rather than a generic clarification.
  if (p.sprint !== null && !kb.sprints.includes(p.sprint))
    gate('unknown_sprint', [`a valid sprint (available: ${kb.sprints.map(s => 'Sprint ' + s).join(', ')})`]);
  else if (p.risk_ids.some(id => !kb.risks.find(x => x.risk_id === id)))
    gate('unknown_risk_id', ['a valid risk ID (R01 to R' + String(kb.risks.length).padStart(2, '0') + ')']);
  else if (p.project_ref === 'NONE') gate('no_project_or_data_identified', intent === 'STATUS' ? ['task board data'] : ['project details']);
  else if (!p.sufficient) gate('router_marked_insufficient');
  else if (p.project_ref === 'OTHER' && ['STATUS', 'MILESTONES', 'COMMS', 'RESOURCES'].includes(intent))
    gate('no_data_loaded_for_other_project', ['task board or timeline data for that project']);
  else if (p.project_ref === 'OTHER' && words < 25)
    gate('other_project_description_too_short', ['scope', 'goals', 'deliverables', 'timeline', 'team size']);
  else if (p.confidence < 0.4) gate('low_router_confidence');
}

// Token usage is estimated (chars / 4): n8n does not expose LLM sub-node usage to Code nodes.
const router_usage_est = { input: Math.ceil((5617 + base.request_safe.length + 110) / 4), output: Math.ceil(rawText.length / 4) };
return { json: { ...base, intent, route, clarify_for, router: p, router_notes: notes, router_raw: rawText.slice(0, 1500), router_usage_est, t_router_done: Date.now() } };

// Mira v2 · Build Fact Pack (data-grounding layer)
// Computes every count, date, linkage and ranking deterministically, then hands the specialist
// agent a brace-free "fact pack" plus an allow-list the Grounding Guard enforces afterwards.
const j = $json;
const route = j.route;
if (!['PLAN', 'RISK', 'STATUS', 'MILESTONES', 'COMMS', 'RESOURCES'].includes(route)) return { json: j };

const kb = j.kb;
const R = j.router;
const rep = kb.reporting_date;
const safe = s => String(s ?? '').replace(/\{/g, '(').replace(/\}/g, ')');
const toMs = iso => Date.parse(iso + 'T00:00:00Z');
const addDays = (iso, n) => new Date(toMs(iso) + n * 86400000).toISOString().slice(0, 10);
const STATES = ['Done', 'In Progress', 'Blocked', 'To Do'];
const countBy = ts => Object.fromEntries(STATES.map(s => [s, ts.filter(t => t.status === s).length]));
const pct = (a, b) => (b ? (100 * a / b).toFixed(1) + '%' : '0.0%');
const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
const flag = t => {
  if (t.status === 'Blocked') return ` · BLOCKED (${safe(t.description)})`;
  if (t.overdue) return ` · OVERDUE by ${plural(-t.days_to_due, 'day')}`;
  if (t.due_soon) return ` · due in ${plural(t.days_to_due, 'day')}`;
  return '';
};
const line = t => `- ${t.task_id} · ${safe(t.task_name)} · ${t.status} · owner ${safe(t.assignee)} · ${t.priority} · ${t.sprint} · due ${t.due_date}${flag(t)}`;
const short = t => `${t.task_id} ${safe(t.task_name)} (${t.status}${t.overdue ? ', overdue' : ''}, owner ${safe(t.assignee)}, due ${t.due_date})`;
const list = (ts, empty = '- None') => (ts.length ? ts.map(line).join('\n') : empty);
const phaseById = id => kb.timeline.find(p => p.phase === id);
const allIds = kb.tasks.map(t => t.task_id);
const hdr = `REPORTING DATE: ${rep} (${kb.date_basis}). Task statuses are the board snapshot, not live progress.`;

function health(scope) {
  const blocked = scope.filter(t => t.status === 'Blocked');
  const blockedHighSoon = blocked.filter(t => t.priority === 'High' && t.days_to_due <= 14);
  const overdue = scope.filter(t => t.overdue);
  const reasons = [];
  if (blocked.length) reasons.push(`${plural(blocked.length, 'blocked task')} (${blocked.map(t => t.task_id).join(', ')})`);
  if (overdue.length) reasons.push(`${plural(overdue.length, 'overdue unfinished task')} (${overdue.map(t => t.task_id).join(', ')})`);
  let rag = 'GREEN';
  if (blockedHighSoon.length || overdue.length >= 2) rag = 'RED';
  else if (blocked.length || overdue.length) rag = 'AMBER';
  return { rag, reasons: reasons.length ? reasons : ['no blocked or overdue tasks in scope'] };
}
const HEALTH_RULE = 'RED if a High-priority task is blocked with due date within 14 days, or 2+ unfinished tasks are overdue; AMBER if any task is blocked or 1 is overdue; otherwise GREEN.';

// milestone ↔ task linkage: tasks due inside the phase window whose name/description shares a keyword
const STOP = new Set(['report', 'final', 'list', 'with', 'project', 'results', 'updated', 'current', 'established', 'completed', 'sessions', 'structure', 'signed', 'process', 'performance', 'future']);
function milestoneTasks(phase, milestone) {
  const inPhase = kb.tasks.filter(t => t.phase === phase.phase);
  const words = milestone.toLowerCase().split(/[^a-z]+/).filter(w => w.length > 4 && !STOP.has(w));
  const hit = inPhase.filter(t => words.some(w => (t.task_name + ' ' + t.description).toLowerCase().includes(w.slice(0, Math.max(5, w.length - 1)))));
  return hit.length ? hit : inPhase;
}
function milestoneSignal(ts) {
  if (!ts.length) return { signal: 'NO LINKED TASKS', why: 'no task-board tasks fall in this phase window' };
  const bad = ts.filter(t => t.status === 'Blocked' || t.overdue);
  if (bad.length) return { signal: 'AT RISK', why: bad.map(t => `${t.task_id} ${t.status === 'Blocked' ? 'blocked' : `overdue by ${plural(-t.days_to_due, 'day')}`}`).join('; ') };
  if (ts.every(t => t.status === 'Done')) return { signal: 'LINKED TASKS DONE', why: 'all linked tasks are Done' };
  if (ts.some(t => t.status === 'In Progress' || t.status === 'Done')) return { signal: 'IN PROGRESS', why: 'linked work started, none blocked or overdue' };
  return { signal: 'NOT STARTED', why: 'linked tasks are all To Do' };
}
function milestonesBetween(fromExcl, toIncl) {
  const out = [];
  for (const p of kb.timeline) {
    if (!p.end_date || !(p.end_date > fromExcl && p.end_date <= toIncl)) continue;
    for (const m of p.milestones) {
      const ts = milestoneTasks(p, m); const s = milestoneSignal(ts);
      out.push({ phase: p, milestone: m, date: p.end_date, tasks: ts, ...s });
    }
  }
  return out;
}
const msLine = m => `- ${safe(m.milestone)} · Phase ${m.phase.phase} ${safe(m.phase.phase_name)} · planned ${m.date} · signal ${m.signal} (${m.why}) · linked tasks: ${m.tasks.map(short).join(', ') || 'none'}`;
const MS_ASSUMPTION = 'The timeline gives week ranges only, so each phase end date is treated as the planned date of that phase deliverables. Tasks are linked to a phase by due date.';

