    for (const t of kb.tasks) if (t.status !== 'Done' && t.priority === 'High') openHighBy[t.assignee] = (openHighBy[t.assignee] || 0) + 1;
    const loaded = Object.entries(openHighBy).filter(([, n]) => n >= 4);
    const scored = kb.risks.map(r => {
      const m = kb.risk_signal_map[r.risk_id] || { labels: [], keywords: [] };
      const linked = kb.tasks.filter(t => t.labels.split(/[;,]/).map(s => s.trim()).some(l => m.labels.includes(l))
        || m.keywords.some(k => t.task_name.toLowerCase().includes(k)));
      let score = 0, bonus = 0;
      for (const t of linked) {
        if (t.status === 'Blocked') score += 5 + (t.priority === 'High' ? 1 : 0);
        else if (t.overdue) score += 3;
        else if (t.status === 'In Progress' && t.due_soon) score += 2;
        else if (t.status !== 'Done' && t.days_to_due <= 14) score += 1;
        if (t.status !== 'Done' && t.priority === 'High') bonus += 0.5;
      }
      score += Math.min(bonus, 1.5);
      let extra = '';
