const hard = [], soft = [];

if (!text) hard.push('empty model output');
const uniq = a => [...new Set(a)];
const tIds = uniq(text.match(/\bT\d{3}\b/g) || []);
const rIds = uniq(text.match(/\bR\d{2}\b/g) || []);
const badT = tIds.filter(id => !fp.allowed_task_ids.includes(id));
const badR = rIds.filter(id => !fp.allowed_risk_ids.includes(id));
if (badT.length) hard.push(`task IDs not in the source or outside scope: ${badT.join(', ')}`);
if (badR.length) hard.push(`risk IDs not in the source register: ${badR.join(', ')}`);
const lower = text.toLowerCase();
const badNames = (fp.forbidden_task_names || []).filter(n => lower.includes(n.toLowerCase()));
if (badNames.length) hard.push(`out-of-scope tasks mentioned: ${badNames.slice(0, 3).join('; ')}`);
const pcts = uniq(text.match(/\d+(?:\.\d+)?%/g) || []);
const norm = p => String(parseFloat(p)) + '%';
const okPcts = new Set((fp.allowed_percentages || []).map(norm));
const badP = pcts.filter(p => !okPcts.has(norm(p)));
if (badP.length) soft.push(`percentages not found in the source data: ${badP.join(', ')}`);

// Owner check: a line citing exactly one task ID that names a different team member, and not the
// real owner, is a likely misattribution (e.g. "Arjun should finish T006" when T006 is Priya's).
if (fp.route !== 'RESOURCES') {
  const owners = Object.fromEntries(src.kb.tasks.map(t => [t.task_id, t.assignee]));
  const people = [...new Set(Object.values(owners))];
  for (const ln of text.split('\n')) {
    const lnIds = uniq(ln.match(/\bT\d{3}\b/g) || []);
    if (lnIds.length !== 1 || !owners[lnIds[0]]) continue;
    const real = owners[lnIds[0]];
    const named = people.filter(p => p !== real && ln.includes(p));
    if (named.length && !ln.includes(real)) soft.push(`${lnIds[0]} is owned by ${real}, not ${named.join(' / ')}`);
  }
}

let output = text;
if (hard.length) {
  output = `${fp.fallback_md}\n\n> ⚠️ **Grounding guard:** the AI narrative was withheld because it ${hard.join('; ')}. The deterministic, source-verified view is shown instead.`;
} else if (soft.length) {
