const missing = (fp.required_task_ids || []).filter(id => !tIds.includes(id));
if (!hard.length && missing.length) {
  const lines = (fp.required_task_lines || []).filter(l => missing.some(id => l.includes(id)));
  output += `\n\n**Other tasks in scope (added by Mira's completeness check):**\n${lines.join('\n')}`;
  soft.push(`added ${missing.length} in-scope task(s) the narrative omitted: ${missing.join(', ')}`);
}
if (fp.verified_footer) output += `\n\n---\n✅ ${fp.verified_footer}`;
output += `\n\n<sub>Mira · ${fp.route} agent · sources: ${src.kb.sources.join(', ')} · reporting date ${src.kb.reporting_date}</sub>`;

return {
