    agent_input: fp.writer_prompt.slice(0, 30000),
    agent_raw: text.slice(0, 30000),
    retrieval_context: fp.facts,
    t_router_done: src.t_router_done, t_facts_done: src.t_facts_done, t_agent_done, t_guard_done: Date.now(),
    guard: { passed: hard.length === 0, used_fallback: hard.length > 0, hard_issues: hard, soft_issues: soft, task_ids_cited: tIds, risk_ids_cited: rIds },
  },
};

