// Builds (1) an OpenTelemetry (OTLP/HTTP JSON) trace for Langfuse's /api/public/otel endpoint and
// (2) Langfuse scores for /api/public/scores. One trace per request, with child observations:
//   orchestrator-router (generation) → route-validator → build-fact-pack (retriever)
//   → <route>-agent (generation) → grounding-guard (guardrail)   |  or  → clarification/unsupported handler
const j = $json;
const MODEL = 'gpt-4o-mini';
const hex = len => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const ns = ms => `${Math.round(ms)}000000`;
const toAttr = (key, v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'boolean') return { key, value: { boolValue: v } };
  if (typeof v === 'number') return Number.isInteger(v) ? { key, value: { intValue: v } } : { key, value: { doubleValue: v } };
  if (Array.isArray(v)) return { key, value: { arrayValue: { values: v.filter(x => x !== null && x !== undefined).map(x => ({ stringValue: String(x) })) } } };
  return { key, value: { stringValue: typeof v === 'string' ? v : JSON.stringify(v) } };
};
const spans = [];
const span = (name, start, end, parentId, attrs, error = false) => {
  const s = {
    traceId: j.trace_id, spanId: hex(16), name, kind: 1,
    startTimeUnixNano: ns(start), endTimeUnixNano: ns(Math.max(end, start)),
    attributes: Object.entries(attrs).map(([k, v]) => toAttr(k, v)).filter(Boolean),
    status: { code: error ? 2 : 1 },
  };
  if (parentId) s.parentSpanId = parentId;
  spans.push(s);
  return s.spanId;
};
