  'langfuse.observation.usage_details': { input: u.input, output: u.output },
  'langfuse.observation.metadata.usage_estimated': true,
} : {});

const t0 = j.started_ms, tEnd = j.completed_ms || Date.now();
const tRouter = j.t_router_done || t0;
const guard = j.guard || {};

const root = span('mira-request', t0, tEnd, null, {
  'langfuse.trace.name': `mira-${String(j.route || 'unknown').toLowerCase()}`,
  'langfuse.session.id': j.session_id,
  'langfuse.trace.input': j.request,
  'langfuse.trace.output': j.output,
  'langfuse.trace.tags': ['mira', j.route, j.source, j.test_id].filter(Boolean),
  'langfuse.release': j.mira_version,
  'langfuse.trace.metadata.route': j.route,
  'langfuse.trace.metadata.intent': j.intent,
  'langfuse.trace.metadata.source': j.source,
  'langfuse.trace.metadata.test_id': j.test_id,
  'langfuse.trace.metadata.latency_ms': j.latency_ms,
  'langfuse.trace.metadata.est_cost_usd': j.est_cost_usd,
  'langfuse.trace.metadata.grounding_passed': guard.passed,
});

span('orchestrator-router', t0, tRouter, root, {
  'langfuse.observation.type': 'generation',
  'langfuse.observation.model.name': MODEL, 'gen_ai.request.model': MODEL,
  'langfuse.observation.model.parameters': { temperature: 0, response_format: 'json_object' },
  'langfuse.observation.input': j.request,
  'langfuse.observation.output': j.router_raw,
