  'langfuse.observation.input': j.router_raw,
  'langfuse.observation.output': { route: j.route, intent: j.intent, clarify_for: j.clarify_for, params: j.router },
});

if (j.handler) {
  span(j.handler, tRouter + 1, tEnd, root, {
    'langfuse.observation.input': j.request,
    'langfuse.observation.output': j.output,
    'langfuse.observation.metadata.llm_calls': 0,
