  span('build-fact-pack', tRouter + 1, tFacts, root, {
    'langfuse.observation.type': 'retriever',
    'langfuse.observation.input': { route: j.route, params: j.router },
    'langfuse.observation.output': j.retrieval_context,
  });
  span(`${String(j.route).toLowerCase()}-agent`, tFacts, tAgent, root, {
    'langfuse.observation.type': 'generation',
    'langfuse.observation.model.name': MODEL, 'gen_ai.request.model': MODEL,
    'langfuse.observation.model.parameters': { temperature: 0.2 },
    'langfuse.observation.input': j.agent_input,
    'langfuse.observation.output': j.agent_raw,
