  T5: [
    ['tasks shown by status', o => has(o, 'in progress', 'to do')],
    ['references actual Sprint 3 tasks', o => has(o, 'T007', 'T008', 'T009', 'T025') && has(o, 'Shortlist AI use cases')],
    ['no invented task IDs', o => ids(o, /\bT\d{3}\b/g).every(t => /^T0(0[1-9]|1\d|2[0-5])$/.test(t))],
  ],
  T6: [
    ['states no task data available', o => has(o, 'no task data')],
    ['no fabricated percentages', o => !/\d+(?:\.\d+)?%/.test(o)],
    ['no fabricated task IDs', o => ids(o, /\bT\d{3}\b/g).length === 0],
  ],
  T7: [
    ['exactly top 3 risks discussed', o => ids(o.split(/remaining/i)[0], /\bR\d{2}\b/g).length >= 3],
    ['risks are from the CSV', o => ids(o, /\bR\d{2}\b/g).every(r => /^R(0[1-9]|10)$/.test(r))],
    ['ranking basis stated', o => any(o, 'evidence', 'task board')],
  ],
  T8: [
    ['identifies T024 blocked', o => has(o, 'T024') && any(o, 'blocked')],
    ['checks due dates', o => any(o, 'overdue', 'days', 'due')],
  ],
  T9: [
    ['asks for scope, goals, deliverables', o => has(o, 'scope', 'goals', 'deliverables')],
    ['no detailed plan from timeline alone', o => !any(o, 'Phase 1', 'Day 1', 'Week 1:')],
  ],
  T10: [
    ['counts match board (5/3/1/16)', o => /Done 5/.test(o) && /In Progress 3/.test(o) && /Blocked 1/.test(o) && /To Do 16/.test(o)],
    ['total 25', o => /Total 25/.test(o) || /\b25\b/.test(o)],
  ],
  T11: [
    ['references timeline milestones', o => MILESTONES.some(m => has(o, m))],
    ['no invented milestones (Gap analysis report present)', o => has(o, 'Gap analysis report')],
  ],
  T12: [
    ['references Sprint 2 tasks', o => sprintIds(2).filter(t => has(o, t)).length >= 2 || any(o, 'Audit existing data infrastructure', 'Map current logistics workflows')],
    ['professional email format', o => /subject:/i.test(o) && /regards/i.test(o)],
    ['no Sprint 3+ tasks', o => ids(o, /\bT\d{3}\b/g).every(t => sprintIds(2).includes(t)) && !any(o, 'Shortlist AI use cases', 'Security review', 'Legal review')],
  ],
};

const rows = cases.map((c, i) => {
  const r = results.find(x => x.test_id === c.test_id) || results[i] || {};
  const o = String(r.output || '');
  const checks = (CHECKS[c.test_id] || []).map(([name, fn]) => { let ok = false; try { ok = !!fn(o); } catch (e) {} return { name, ok }; });
  const routeOk = r.route === c.expected_route;
  const passed = routeOk && checks.every(x => x.ok);
  return {
    test_id: c.test_id, input: c.chatInput, expected_route: c.expected_route, actual_route: r.route || 'ERROR',
    route_ok: routeOk, checks_passed: `${checks.filter(x => x.ok).length}/${checks.length}`,
    failed_checks: checks.filter(x => !x.ok).map(x => x.name).join('; ') || '—',
    result: passed ? 'PASS' : 'FAIL', guard_fallback: r.guard?.used_fallback ?? null, latency_ms: r.latency_ms ?? null,
    trace_id: r.trace_id || null, est_cost_usd: r.est_cost_usd ?? null,
    output_preview: o.slice(0, 300),
  };
});
const passCount = rows.filter(r => r.result === 'PASS').length;
const avgLatency = Math.round(rows.reduce((s, r) => s + (r.latency_ms || 0), 0) / rows.length);
return [
  { json: { test_id: 'SUMMARY', result: `${passCount}/${rows.length} PASS`, route_accuracy: `${rows.filter(r => r.route_ok).length}/${rows.length}`, avg_latency_ms: avgLatency, est_total_cost_usd: Number(rows.reduce((a, r) => a + (r.est_cost_usd || 0), 0).toFixed(5)), guard_fallbacks: rows.filter(r => r.guard_fallback).length, run_at: new Date().toISOString() } },
  ...rows.map(r => ({ json: r })),
];

// Mira v2 · Build Eval Scores — attaches baseline-eval results to each test's Langfuse trace.
const out = [];
$input.all().forEach((it, idx) => {
  const r = it.json;
  if (!r.trace_id) return; // skips the SUMMARY row
  const [ok, total] = String(r.checks_passed || '0/0').split('/').map(Number);
  out.push({ json: { id: `${r.trace_id}-baseline_pass`, traceId: r.trace_id, name: 'baseline_pass', value: r.result === 'PASS' ? 1 : 0,
    dataType: 'BOOLEAN', comment: `${r.test_id}: ${r.failed_checks}` }, pairedItem: { item: idx } });
  out.push({ json: { id: `${r.trace_id}-baseline_checks`, traceId: r.trace_id, name: 'baseline_checks', value: total ? ok / total : 0,
    dataType: 'NUMERIC', comment: `${r.test_id}: ${r.checks_passed} checks` }, pairedItem: { item: idx } });
});
return out;
